import React, { useEffect, useMemo, useRef, useState } from 'react';
import { api, MEDIA_URL, session, securityMode } from './api.js';
import { crearSecuenciaTraduccion } from './traductor.js';
import { actividadUltimosDias, calcularLogros } from './logros.js';
import { estadoRacha, estadoVidas, listarRangos, obtenerRango, seCompletoHoy, VIDAS_MAXIMAS } from './progreso.js';
import { ArrowLeft, ArrowRight, Award, Bell, BookOpen, CalendarDays, Check, ChevronRight, CircleUserRound, Crown, Eye, EyeOff, Flame, Heart, Home, Languages, Library, LockKeyhole, LogOut, Mail, Medal, Menu, Mic, Pause, Play, Search, Settings, ShieldCheck, Sparkles, Star, Target, Trophy, UserPlus, Users, Volume2, X, Zap } from 'lucide-react';

const normalize = text => String(text).normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/[^a-z0-9ñ]+/g, ' ').trim();
const videoSrc = path => `${MEDIA_URL}${path}?formato=h264`;
const shuffle = list => [...list].sort(() => Math.random() - .5);
const guatemalaDay = () => new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Guatemala', year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date());
const avatars = { wave: '🤟🏻', duck: '🦆', unicorn: '🦄', chick: '🐥', fox: '🦊', panda: '🐼', frog: '🐸', cat: '🐱', dog: '🐶', koala: '🐨', butterfly: '🦋', spark: '✨', heart: '💜', star: '⭐', book: '📚', rocket: '🚀', sun: '☀️' };
const avatarNames = { wave: 'Seña', duck: 'Pato', unicorn: 'Unicornio', chick: 'Pollito', fox: 'Zorro', panda: 'Panda', frog: 'Rana', cat: 'Gato', dog: 'Perro', koala: 'Koala', butterfly: 'Mariposa', spark: 'Brillos', heart: 'Corazón', star: 'Estrella', book: 'Libros', rocket: 'Cohete', sun: 'Sol' };

function Logo({ compact = false }) { return <div className="logo"><span className="logo-mark">S</span>{!compact && <span>Sing<span>AI</span></span>}</div>; }
function Button({ children, kind = 'primary', className = '', ...props }) { return <button className={`button ${kind} ${className}`} {...props}>{children}</button>; }
function Spinner() { return <div className="screen-center"><div className="loader"/><p>Preparando tu experiencia…</p></div>; }
function Notice({ text, type = 'error' }) { return text ? <div className={`notice ${type}`}>{text}</div> : null; }

function PasswordField({ value, onChange, autoComplete, placeholder = 'Mínimo 8 caracteres' }) {
  const [visible, setVisible] = useState(false);
  return <div className="input-wrap"><LockKeyhole/><input type={visible ? 'text' : 'password'} value={value} onChange={onChange} placeholder={placeholder} autoComplete={autoComplete} required minLength="8"/><button type="button" className="password-toggle" onClick={() => setVisible(show => !show)} aria-label={visible ? 'Ocultar contraseña' : 'Mostrar contraseña'} title={visible ? 'Ocultar contraseña' : 'Mostrar contraseña'}>{visible ? <EyeOff/> : <Eye/>}</button></div>;
}

function SignVideo({ src, autoplay = true, loop = false, onEnded }) {
  const media = useRef(null); const [paused, setPaused] = useState(!autoplay); const [error, setError] = useState('');
  useEffect(() => {
    const video = media.current; if (!video) return;
    setError(''); setPaused(!autoplay);
    video.muted = true;
    if (!autoplay) { video.pause(); return; }
    const start = () => video.play().catch(() => setPaused(true));
    if (video.readyState >= HTMLMediaElement.HAVE_FUTURE_DATA) start();
    else video.addEventListener('canplay', start, { once: true });
    return () => video.removeEventListener('canplay', start);
  }, [src, autoplay]);
  const toggle = () => {
    const video = media.current; if (!video) return;
    setError(''); video.muted = true;
    if (video.paused) {
      if (video.ended) video.currentTime = 0;
      video.play().catch(() => setPaused(true));
    }
    else video.pause();
  };
  return <><video ref={media} src={src} autoPlay={autoplay} loop={loop} muted playsInline preload="auto"
    onPlay={() => { setPaused(false); setError(''); }} onPause={() => setPaused(true)}
    onError={() => setError('No se pudo cargar este video.')} onEnded={onEnded}/>
    <button type="button" className="video-toggle" onClick={toggle} aria-label={paused ? 'Reproducir video' : 'Pausar video'} title={paused ? 'Reproducir' : 'Pausar'}>{paused ? <Play/> : <Pause/>}</button>
    {error && <div className="video-error"><X/>{error}</div>}</>;
}

function AuthScreen({ onAuth }) {
  const [mode, setMode] = useState('login'); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState('');
  const [form, setForm] = useState({ name: '', email: '', password: '', learningGoal: 'comunicarme' });
  const [challenge, setChallenge] = useState(''); const [code, setCode] = useState('');
  const update = e => setForm({ ...form, [e.target.name]: e.target.value });
  const submit = async e => {
    e.preventDefault(); setBusy(true); setError(''); setMessage('');
    try {
      if (mode === 'forgot') {
        const result = await api('/auth/forgot-password', { method: 'POST', body: { email: form.email } }); setMessage(result.message); return;
      }
      if (mode === 'code') {
        const result = await api('/auth/login/code', { method: 'POST', body: { challenge, code } });
        session.token = result.token; onAuth(result.user); return;
      }
      const result = await api(`/auth/${mode}`, { method: 'POST', body: form });
      if (result.requiresVerification) { setMessage(result.message); setMode('verify-sent'); return; }
      if (result.requiresCode) { setChallenge(result.challenge); setMessage(result.message); setMode('code'); return; }
      session.token = result.token; onAuth(result.user);
    } catch (err) { setError(err.message); } finally { setBusy(false); }
  };
  return <div className="auth-shell"><main className="auth-panel"><div className="auth-card">
      <div className="auth-brand"><Logo/><p>Aprende lengua de señas a tu ritmo</p></div>
      {mode === 'verify-sent' ? <div className="verify-sent"><div className="verify-icon"><Mail/></div><span className="eyebrow">ACTIVA TU CUENTA</span><h2>Revisa tu correo</h2><p className="muted">Enviamos un enlace de verificación a <strong>{form.email}</strong>. Debes abrirlo antes de poder iniciar sesión.</p><Notice text={message} type="success"/><Button onClick={() => {setMode('login');setMessage('')}}>Volver al inicio</Button></div> : <>
      <span className="eyebrow">{mode === 'register' ? 'EMPIEZA HOY' : mode === 'forgot' ? 'RECUPERA TU CUENTA' : mode === 'code' ? 'SEGUNDO PASO' : 'BIENVENIDO A SINGAI'}</span>
      <h2>{mode === 'register' ? 'Crea tu perfil' : mode === 'forgot' ? 'Cambia tu contraseña' : mode === 'code' ? 'Confirma que eres tú' : 'Comienza tu aprendizaje'}</h2>
      <p className="muted">{mode === 'register' ? 'Tu progreso estará siempre contigo.' : mode === 'forgot' ? 'Recibirás un enlace para elegir una nueva contraseña.' : mode === 'code' ? <>Escribe el código enviado a <strong>{form.email}</strong>.</> : 'Inicia sesión o crea una cuenta para comenzar.'}</p>
      {mode === 'login' && <div className="auth-security"><ShieldCheck/><span><strong>{securityMode === 'codigo-correo' ? 'Acceso con doble comprobación' : 'Acceso protegido por Firebase'}</strong><small>{securityMode === 'codigo-correo' ? 'Contraseña y código personal enviado a tu correo.' : 'Contraseña, correo verificado y sesión privada del navegador.'}</small></span></div>}
      <form onSubmit={submit}>
        {mode === 'register' && <label>Tu nombre<div className="input-wrap"><CircleUserRound/><input name="name" value={form.name} onChange={update} placeholder="¿Cómo te llamas?" autoComplete="name" required/></div></label>}
        {mode !== 'code' && <label>Correo electrónico<div className="input-wrap"><Mail/><input name="email" type="email" value={form.email} onChange={update} placeholder="tu@correo.com" autoComplete="email" required/></div></label>}
        {(mode === 'login' || mode === 'register') && <label>Contraseña<PasswordField value={form.password} onChange={e => setForm({...form, password: e.target.value})} autoComplete={mode === 'login' ? 'current-password' : 'new-password'}/></label>}
        {mode === 'code' && <><label>Código de seguridad<div className="input-wrap code-input"><ShieldCheck/><input value={code} onChange={e=>setCode(e.target.value.replace(/\D/g,'').slice(0,6))} inputMode="numeric" autoComplete="one-time-code" placeholder="000000" pattern="\d{6}" required autoFocus/></div></label><p className="spam-help">Puede tardar un momento. Si no aparece en tu bandeja principal, revisa con calma Spam o Correo no deseado.</p></>}
        {mode === 'register' && <label>Quiero aprender para<select name="learningGoal" value={form.learningGoal} onChange={update}><option value="comunicarme">Comunicarme mejor</option><option value="familia">Hablar con mi familia</option><option value="trabajo">Usarlo en mi trabajo</option><option value="curiosidad">Aprender algo nuevo</option></select></label>}
        <Notice text={error}/><Notice text={message} type="success"/>
        <Button disabled={busy}>{busy ? 'Un momento…' : mode === 'register' ? 'Crear cuenta y verificar correo' : mode === 'login' ? 'Entrar a SingAI' : mode === 'code' ? 'Verificar y entrar' : 'Enviar enlace'}<ArrowRight/></Button>
      </form>
      {mode === 'login' && <div className="auth-links"><button onClick={() => setMode('forgot')}>Olvidé mi contraseña</button></div>}
      {(mode === 'login' || mode === 'register') && <div className="auth-switch">{mode === 'register' ? <>¿Ya tienes cuenta? <button onClick={() => setMode('login')}>Inicia sesión</button></> : <>¿Primera vez aquí? <button onClick={() => setMode('register')}>Crea una cuenta</button></>}</div>}
      {mode === 'forgot' && <button className="back-link" onClick={() => setMode('login')}><ArrowLeft/> Volver al inicio</button>}
      {mode === 'code' && <button className="back-link" onClick={() => {setMode('login');setCode('');setChallenge('');setMessage('')}}><ArrowLeft/> Usar otra cuenta</button>}
      </>}
    </div></main>
  </div>;
}

function LinkAction() {
  const params = new URLSearchParams(location.search); const token = params.get('token') || params.get('oobCode') || ''; const [password, setPassword] = useState(''); const [state, setState] = useState({ busy: false, error: '', done: '' });
  const reset = async e => { e.preventDefault(); setState({ busy: true, error: '', done: '' }); try { const r = await api('/auth/reset-password', { method: 'POST', body: { token, password } }); setState({ busy: false, error: '', done: r.message }); } catch (err) { setState({ busy: false, error: err.message, done: '' }); } };
  return <div className="simple-action"><Logo/><div className="auth-card"><span className="eyebrow">SEGURIDAD</span><h1>Nueva contraseña</h1><p className="muted">Elige una contraseña de al menos 8 caracteres.</p><form onSubmit={reset}><label>Contraseña<PasswordField value={password} onChange={e => setPassword(e.target.value)} autoComplete="new-password"/></label><Notice text={state.error}/><Notice text={state.done} type="success"/><Button disabled={state.busy}>{state.busy ? 'Guardando…' : 'Guardar contraseña'}</Button></form>{state.done && <button className="back-link" onClick={() => location.assign('/')}>Ir al inicio</button>}</div></div>;
}

function VerifyAction() {
  const token = new URLSearchParams(location.search).get('token') || '';
  const [state, setState] = useState({ busy: true, error: '', done: '' });
  useEffect(() => { api('/auth/magic/verify', { method: 'POST', body: { token } })
    .then(() => setState({ busy: false, error: '', done: 'Correo verificado correctamente. Ya puedes iniciar sesión.' }))
    .catch(error => setState({ busy: false, error: error.message, done: '' })); }, [token]);
  return <div className="simple-action"><Logo/><div className="auth-card"><span className="eyebrow">SEGURIDAD</span><h1>Verificación de correo</h1><p className="muted">{state.busy ? 'Comprobando tu enlace…' : 'Protegemos tu cuenta antes de permitir el acceso.'}</p><Notice text={state.error}/><Notice text={state.done} type="success"/><button className="back-link" onClick={() => location.assign('/')}><ArrowLeft/> Ir al inicio</button></div></div>;
}

const navItems = [{ id: 'inicio', label: 'Inicio', Icon: Home }, { id: 'aprender', label: 'Aprender', Icon: BookOpen }, { id: 'diccionario', label: 'Diccionario', Icon: Library }, { id: 'traductor', label: 'Traductor', Icon: Languages }, { id: 'rangos', label: 'Rangos', Icon: Award }, { id: 'logros', label: 'Logros', Icon: Trophy }, { id: 'amigos', label: 'Amigos', Icon: Users }, { id: 'seguridad', label: 'Seguridad', Icon: ShieldCheck }, { id: 'perfil', label: 'Mi perfil', Icon: CircleUserRound }];
function Shell({ user, profile, page, setPage, children, logout, pendingCount = 0 }) {
  const [open, setOpen] = useState(false); const [clock, setClock] = useState(Date.now()); const rank = obtenerRango(profile?.xp); const lifeState = estadoVidas(profile, clock); const streakState = estadoRacha(profile, guatemalaDay());
  useEffect(() => { const timer = setInterval(() => setClock(Date.now()), 60000); return () => clearInterval(timer); }, []);
  useEffect(() => { if (!profile?.heartsBlockedUntil) return; setClock(Date.now()); const timer = setInterval(() => setClock(Date.now()), 1000); return () => clearInterval(timer); }, [profile?.heartsBlockedUntil]);
  const lifeMs = lifeState.bloqueadoHasta ? Math.max(0, new Date(lifeState.bloqueadoHasta).getTime() - clock) : 0;
  const lifeSeconds = Math.ceil(lifeMs / 1000); const lifeCountdown = `${String(Math.floor(lifeSeconds / 60)).padStart(2, '0')}:${String(lifeSeconds % 60).padStart(2, '0')}`;
  return <div className="app-shell">
    <aside className={open ? 'sidebar open' : 'sidebar'}><div className="side-head"><Logo/><button className="icon-btn close-menu" onClick={() => setOpen(false)}><X/></button></div><nav>{navItems.map(({ id, label, Icon }) => <button key={id} className={page === id ? 'active' : ''} onClick={() => {setPage(id); setOpen(false)}}><Icon/><span>{label}</span>{id === 'amigos' && pendingCount > 0 && <b className="nav-badge">{pendingCount > 9 ? '9+' : pendingCount}</b>}{page === id && <i/>}</button>)}</nav><div className={`side-streak ${streakState.estado}`}><div><Flame/><strong>{streakState.racha} días</strong></div><p>{streakState.mensaje}</p></div><button className="logout" onClick={logout}><LogOut/> Cerrar sesión</button></aside>
    <div className="app-main"><header className="topbar"><button className="icon-btn mobile-menu" onClick={() => setOpen(true)}><Menu/></button><div className="top-spacer"/><div className={`stat-chip lives-chip ${lifeState.bloqueado ? 'blocked' : ''}`} title={lifeState.bloqueado ? `Tus vidas vuelven en ${lifeCountdown}` : `${lifeState.vidas} vidas disponibles`}><Heart/><strong>{lifeState.bloqueado ? lifeCountdown : lifeState.vidas}</strong><span>{lifeState.bloqueado ? 'recarga' : 'vidas'}</span></div><div className={`stat-chip streak-chip ${streakState.estado}`} title={streakState.mensaje}><Flame/><strong>{streakState.racha}</strong><span>racha</span></div><div className="stat-chip purple rank-chip"><Award/><strong>{rank.nombre}</strong><span>{rank.xp} XP</span></div><button className="avatar" onClick={() => setPage('perfil')} aria-label="Abrir perfil">{avatars[profile?.avatar] || '🤟🏻'}</button></header>{lifeState.bloqueado && <div className="lives-warning"><Heart/><span><strong>Sin vidas por ahora.</strong> Tus cinco corazones vuelven en</span><b>{lifeCountdown}</b></div>}<main className="content">{children}</main></div>
    {open && <div className="scrim" onClick={() => setOpen(false)}/>}
  </div>;
}

function Welcome({ profile, catalog, progress, startLesson, setPage }) {
  const complete = progress.completedLessonIds?.length || 0; const total = catalog.units.reduce((n, u) => n + u.lessons.length, 0); const pct = total ? Math.round(complete / total * 100) : 0;
  const rank = obtenerRango(profile.xp);
  const next = catalog.units.flatMap(u => u.lessons.map(l => ({...l, unit: u}))).find(l => !progress.completedLessonIds?.includes(l.id));
  const currentDay = guatemalaDay();
  const streak = estadoRacha(profile, currentDay);
  const completedToday = progress.lessons?.some(item => seCompletoHoy(item.completedAt, currentDay));
  return <div className="page enter"><section className="welcome"><div><span className="eyebrow">TU CAMINO DE APRENDIZAJE</span><h1>¡Hola, {profile.displayName}! <span>👋🏻</span></h1><p>Hoy es un buen día para aprender una nueva forma de conectar.</p></div><div className="date-pill"><CalendarDays/><div><small>HOY</small><strong>{new Intl.DateTimeFormat('es-GT',{weekday:'long',day:'numeric',month:'short'}).format(new Date())}</strong></div></div></section>
    <section className="hero-card"><div className="hero-copy"><span className="mini-tag"><Sparkles/> {complete ? 'CONTINÚA DONDE QUEDASTE' : 'TU PRIMER PASO'}</span><h2>{next ? next.unit.title : '¡Completaste todo el camino!'}</h2><p>{next ? `${next.title} · ${next.description}` : 'Puedes repetir cualquier lección para fortalecer tu memoria.'}</p><div className="hero-progress"><div><span>Progreso total</span><strong>{pct}%</strong></div><div className="track"><i style={{width:`${pct}%`}}/></div></div>{next && <Button onClick={() => startLesson(next)}><Play/> {complete ? 'Continuar lección' : 'Comencemos'}</Button>}</div><div className="hero-visual"><div className="bubble back">✦</div><div className="bubble main">🤟🏻</div><div className="bubble tiny">✓</div></div></section>
    <div className="section-title"><div><span className="eyebrow">TU PROGRESO</span><h2>Esta semana</h2></div><button onClick={() => setPage('aprender')}>Ver ruta <ChevronRight/></button></div>
    <section className="metrics"><article><div className="metric-icon orange"><Flame/></div><div><strong>{streak.racha}</strong><span>Días de racha</span></div><small>{streak.mensaje}</small></article><article><div className="metric-icon violet"><Award/></div><div><strong className="rank-name">{rank.nombre}</strong><span>{rank.xp} XP acumulados</span></div><small>{rank.esMaximo ? 'Rango máximo' : `${rank.xpSiguiente - rank.xp} XP para subir`}</small></article><article><div className="metric-icon teal"><Trophy/></div><div><strong>{complete}</strong><span>Lecciones listas</span></div><small>de {total}</small></article></section>
    <ActivitySummary progress={progress} profile={profile} onOpenAchievements={() => setPage('logros')}/>
    <section className="daily-card"><div><span className="eyebrow">OBJETIVO DIARIO</span><h2>Una lección al día hace la diferencia</h2><p>Las sesiones cortas y constantes ayudan a recordar mejor cada seña.</p></div><div className="goal-ring"><svg viewBox="0 0 80 80"><circle cx="40" cy="40" r="32"/><circle className="fill" cx="40" cy="40" r="32" strokeDasharray="201" strokeDashoffset={completedToday ? 0 : 201}/></svg><span>{completedToday ? <Check/> : '0/1'}</span></div></section>
  </div>;
}

function ActivitySummary({ progress, profile, onOpenAchievements }) {
  const days = actividadUltimosDias(progress.lessons || []); const achievements = calcularLogros(profile, progress, guatemalaDay());
  const unlocked = achievements.filter(item => item.desbloqueado).length;
  return <section className="activity-card"><div><span className="eyebrow">ACTIVIDAD RECIENTE</span><h2>Tu semana en SingAI</h2><p>{unlocked} de {achievements.length} logros desbloqueados</p><button onClick={onOpenAchievements}>Ver todos los logros <ChevronRight/></button></div><div className="activity-days">{days.map(day => <div key={day.fecha} className={day.activo ? 'active' : ''} title={day.fecha}><i>{day.activo ? <Check/> : null}</i><span>{day.etiqueta}</span></div>)}</div></section>;
}

function Achievements({ profile, progress }) {
  const achievements = calcularLogros(profile, progress, guatemalaDay()); const unlocked = achievements.filter(item => item.desbloqueado).length;
  return <div className="page enter"><div className="page-heading"><span className="eyebrow">TU COLECCIÓN</span><h1>Logros</h1><p>Cada insignia reconoce una parte real de tu aprendizaje.</p></div><section className="achievement-summary"><Trophy/><div><strong>{unlocked} de {achievements.length}</strong><span>logros desbloqueados</span></div><div className="track"><i style={{width:`${Math.round(unlocked / achievements.length * 100)}%`}}/></div></section><section className="achievement-grid">{achievements.map(item => <article key={item.id} className={item.desbloqueado ? 'unlocked' : 'locked'}><div>{item.desbloqueado ? item.icono : '🔒'}</div><span>{item.desbloqueado ? 'DESBLOQUEADO' : 'PENDIENTE'}</span><h2>{item.titulo}</h2><p>{item.descripcion}</p></article>)}</section></div>;
}

function SecurityCenter({ user }) {
  const [state, setState] = useState({ loading: true, events: [], error: '', expiresAt: session.expiresAt });
  useEffect(() => { api('/security/events').then(data => setState({ loading: false, error: '', ...data })).catch(error => setState(current => ({ ...current, loading: false, error: error.message }))); }, []);
  const expires = state.expiresAt ? new Intl.DateTimeFormat('es-GT', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(state.expiresAt)) : 'Al cerrar esta pestaña';
  return <div className="page narrow enter"><div className="page-heading"><span className="eyebrow">PROTECCIÓN DE CUENTA</span><h1>Centro de seguridad</h1><p>Consulta cómo protegemos tu acceso y revisa la actividad reciente.</p></div><section className="security-center"><div className="security-hero"><ShieldCheck/><div><span>ESTADO</span><h2>Cuenta protegida</h2><p>Correo verificado y sesión privada del navegador.</p></div></div><div className="security-facts"><article><Mail/><div><strong>{user.email}</strong><span>Correo verificado</span></div></article><article><LockKeyhole/><div><strong>30 minutos</strong><span>Cierre por inactividad</span></div></article><article><LogOut/><div><strong>{expires}</strong><span>Vencimiento estimado</span></div></article></div><div className="security-events"><h2>Accesos recientes</h2><p>Si no reconoces alguno, cambia tu contraseña inmediatamente.</p>{state.loading ? <p>Cargando actividad…</p> : state.events.length ? state.events.map(event => <article key={event.id}><div><Check/></div><span><strong>Inicio de sesión correcto</strong><small>{event.device}</small></span><time>{new Intl.DateTimeFormat('es-GT',{dateStyle:'medium',timeStyle:'short'}).format(new Date(event.createdAt))}</time></article>) : <p className="muted">El historial empezará a mostrarse con tus próximos accesos.</p>}<Notice text={state.error}/></div></section></div>;
}

function Learn({ catalog, progress, startLesson }) {
  let unlocked = true;
  return <div className="page narrow enter"><div className="page-heading"><span className="eyebrow">RUTA PERSONALIZADA</span><h1>Aprende paso a paso</h1><p>Cada unidad construye sobre la anterior. Completa las lecciones y gana experiencia.</p></div>
    <div className="learning-path">{catalog.units.map((unit, unitIndex) => { const completeCount = unit.lessons.filter(l => progress.completedLessonIds.includes(l.id)).length; const unitUnlocked = unitIndex === 0 || catalog.units[unitIndex - 1].lessons.some(l => progress.completedLessonIds.includes(l.id)); return <section className={`unit ${!unitUnlocked ? 'locked' : ''}`} key={unit.id} style={{'--unit': unit.color}}><header><div className="unit-number">{unitUnlocked ? unitIndex + 1 : <LockKeyhole/>}</div><div><span>UNIDAD {unitIndex + 1}</span><h2>{unit.title}</h2><p>{unit.description}</p></div><strong>{completeCount}/{unit.lessons.length}</strong></header><div className="lesson-nodes">{unit.lessons.map((lesson, i) => { const done = progress.completedLessonIds.includes(lesson.id); return <button key={lesson.id} className={`lesson-node ${done ? 'done' : ''}`} disabled={!unitUnlocked} onClick={() => startLesson({...lesson, unit})}><span>{done ? <Check/> : i + 1}</span><div><strong>{lesson.title}</strong><small>{lesson.description}</small></div><em>{done ? 'Completada' : `${lesson.xp} XP`}</em><ChevronRight/></button>})}</div></section>})}</div>
  </div>;
}

function Lesson({ lesson, catalog, profile, onClose, onComplete, onMistake, autoplay = true }) {
  const allSigns = useMemo(() => catalog.units.flatMap(u => u.lessons.flatMap(l => l.signs)), [catalog]);
  const questions = useMemo(() => lesson.signs.map(sign => ({ sign, options: shuffle([sign.term, ...shuffle(allSigns.filter(x => x.id !== sign.id)).slice(0, 3).map(x => x.term)]) })), [lesson]);
  const initialLives = estadoVidas(profile);
  const [phase, setPhase] = useState('learn'); const [learnIndex, setLearnIndex] = useState(0); const [reviewOnly, setReviewOnly] = useState(false); const [index, setIndex] = useState(0); const [picked, setPicked] = useState(''); const [correct, setCorrect] = useState(0); const [lives, setLives] = useState(initialLives.vidas); const [blockedUntil, setBlockedUntil] = useState(initialLives.bloqueadoHasta); const [exhausted, setExhausted] = useState(initialLives.bloqueado); const [xpLost, setXpLost] = useState(0); const [now, setNow] = useState(Date.now()); const [finished, setFinished] = useState(false); const [saving, setSaving] = useState(false); const [registeringMistake, setRegisteringMistake] = useState(false); const [xpAwarded, setXpAwarded] = useState(0); const [saveError, setSaveError] = useState('');
  useEffect(() => { if (!blockedUntil) return; const timer = setInterval(() => setNow(Date.now()), 1000); return () => clearInterval(timer); }, [blockedUntil]);
  const remainingMs = blockedUntil ? Math.max(0, new Date(blockedUntil).getTime() - now) : 0;
  const remainingSeconds = Math.ceil(remainingMs / 1000); const remaining = `${String(Math.floor(remainingSeconds / 60)).padStart(2, '0')}:${String(remainingSeconds % 60).padStart(2, '0')}`;
  const q = questions[index]; const score = Math.round(correct / questions.length * 100);
  const hearts = <div className="lesson-hearts" aria-label={`${lives} de ${VIDAS_MAXIMAS} vidas`}>{Array.from({length:VIDAS_MAXIMAS},(_,i)=><Heart key={i} className={i < lives ? 'full' : 'empty'}/>)}</div>;
  const resetQuiz = () => { setIndex(0); setPicked(''); setCorrect(0); setSaveError(''); };
  const choose = async option => {
    if (picked || registeringMistake) return;
    setPicked(option); setSaveError('');
    if (option === q.sign.term) { setCorrect(v => v + 1); return; }
    setRegisteringMistake(true);
    try {
      const result = await onMistake(); setLives(result.vidas); setBlockedUntil(result.bloqueadoHasta); setXpLost(result.xpPerdida || 0);
      if (result.bloqueado) setExhausted(true);
    } catch { setPicked(''); setSaveError('No pudimos registrar el intento. Revisa tu conexión e inténtalo otra vez.'); }
    finally { setRegisteringMistake(false); }
  };
  const next = async () => { if (index < questions.length - 1) { setIndex(v => v + 1); setPicked(''); setSaveError(''); } else { setSaving(true); setSaveError(''); try { const result = await onComplete(lesson.id, score); setXpAwarded(result.xpAwarded); setFinished(true); } catch { setSaveError('No pudimos guardar tu progreso. Revisa la conexión y pulsa nuevamente.'); } finally { setSaving(false); } } };
  const review = () => { setReviewOnly(true); setLearnIndex(0); setPhase('learn'); setExhausted(false); };
  const retry = () => { setLives(VIDAS_MAXIMAS); setBlockedUntil(null); setXpLost(0); setReviewOnly(false); setLearnIndex(0); resetQuiz(); setPhase('learn'); setExhausted(false); };
  if (exhausted) return <div className="lesson-overlay"><div className="lives-card enter"><div className="broken-heart"><Heart/></div><span className="eyebrow">SIN INTENTOS</span><h1>Se terminaron tus cinco vidas</h1><p>{remainingMs > 0 ? <>Podrás responder nuevamente en <strong>{remaining}</strong>.</> : 'Tus cinco vidas ya están disponibles nuevamente.'}</p>{xpLost > 0 && <div className="xp-penalty"><Zap/> Perdiste {xpLost} XP</div>}<Button onClick={review} kind="secondary"><BookOpen/> Volver a repasar</Button>{remainingMs === 0 && <Button onClick={retry}><Play/> Intentar nuevamente</Button>}<button className="back-link" onClick={onClose}>Volver a la ruta</button></div></div>;
  if (finished) return <div className="lesson-overlay"><div className="result-card enter"><div className="result-burst">🏆</div><span className="eyebrow">LECCIÓN TERMINADA</span><h1>{score >= 80 ? '¡Excelente trabajo!' : '¡Buen intento!'}</h1><p>{score >= 80 ? 'Tus manos ya recuerdan nuevas formas de conectar.' : 'La práctica hace la diferencia. Puedes repetirla cuando quieras.'}</p><div className="result-stats"><div><Zap/><strong>+{xpAwarded}</strong><span>XP guardados</span></div><div><Target/><strong>{score}%</strong><span>Precisión</span></div></div><Button onClick={onClose}>Volver a la ruta <ArrowRight/></Button></div></div>;
  if (phase === 'learn') {
    const sign = lesson.signs[learnIndex]; const last = learnIndex === lesson.signs.length - 1;
    const finishReview = () => { if (!last) return setLearnIndex(value => value + 1); if (reviewOnly && remainingMs > 0) return setExhausted(true); if (reviewOnly) retry(); else setPhase('quiz'); };
    return <div className="lesson-overlay"><div className="lesson-top"><button className="icon-btn" onClick={onClose}><X/></button><div className="lesson-track"><i style={{width:`${(learnIndex + 1) / lesson.signs.length * 100}%`}}/></div><span>{learnIndex + 1} de {lesson.signs.length}</span>{hearts}</div><div className="quiz-card lesson-intro"><div className="quiz-label"><BookOpen/> {reviewOnly ? 'REPASO' : 'PRIMERO, APRENDE'}</div><h1>Esta seña significa</h1><div className="intro-term">{sign.term}</div><div className="video-frame"><SignVideo key={sign.video} src={videoSrc(sign.video)} autoplay={autoplay} loop/><span>Observa y repite la seña</span></div><p className="intro-help">Mira con atención la posición y el movimiento de las manos. Después te preguntaremos qué significa.</p><div className="intro-actions"><Button kind="secondary" disabled={learnIndex === 0} onClick={() => setLearnIndex(value => value - 1)}><ArrowLeft/> Anterior</Button><Button onClick={finishReview}>{last ? reviewOnly ? remainingMs > 0 ? 'Ver tiempo restante' : 'Intentar nuevamente' : 'Comenzar preguntas' : 'Siguiente seña'} <ArrowRight/></Button></div></div></div>;
  }
  return <div className="lesson-overlay"><div className="lesson-top"><button className="icon-btn" onClick={onClose}><X/></button><div className="lesson-track"><i style={{width:`${index/questions.length*100}%`}}/></div><span>{index + 1} de {questions.length}</span>{hearts}</div><div className="quiz-card"><div className="quiz-label"><Volume2/> OBSERVA LA SEÑA</div><h1>¿Qué significa este gesto?</h1>{saveError && <Notice text={saveError}/>}<div className="video-frame"><SignVideo key={q.sign.video} src={videoSrc(q.sign.video)} autoplay={autoplay} loop/><span>Video en lengua de señas</span></div><div className="answers">{q.options.map((option, i) => <button key={option} onClick={() => choose(option)} className={picked ? option === q.sign.term ? 'correct' : option === picked ? 'wrong' : 'dim' : ''}><kbd>{i + 1}</kbd>{option}{picked && option === q.sign.term && <Check/>}{picked === option && option !== q.sign.term && <X/>}</button>)}</div></div>{picked && <div className={`feedback ${picked === q.sign.term ? 'good' : 'bad'}`}><div>{picked === q.sign.term ? <Check/> : <X/>}</div><p><strong>{picked === q.sign.term ? '¡Correcto!' : `La respuesta era “${q.sign.term}”`}</strong><span>{picked === q.sign.term ? '¡Sigue así!' : `Te quedan ${Math.max(0,lives)} vidas.`}</span></p><Button onClick={next} disabled={saving || registeringMistake}>{saving ? 'Guardando…' : registeringMistake ? 'Registrando…' : index === questions.length - 1 ? 'Finalizar' : 'Continuar'}<ArrowRight/></Button></div>}</div>;
}

function Dictionary({ catalog, autoplay = true }) {
  const signs = useMemo(() => catalog.units.flatMap(u => u.lessons.flatMap(l => l.signs.map(s => ({...s, unit: u.title, color: u.color})))), [catalog]); const [query, setQuery] = useState(''); const [unit, setUnit] = useState('Todas'); const [selected, setSelected] = useState(signs[0]); const [previewOpen, setPreviewOpen] = useState(false);
  const filtered = signs.filter(s => (unit === 'Todas' || s.unit === unit) && normalize(s.term).includes(normalize(query)));
  const openPreview = sign => { setSelected(sign); setPreviewOpen(true); };
  return <div className="page enter"><div className="page-heading row"><div><span className="eyebrow">EXPLORA A TU RITMO</span><h1>Diccionario visual</h1><p>Busca una palabra y observa cómo se expresa.</p></div></div><div className="dictionary-layout"><section><div className="search-box"><Search/><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Buscar una seña…"/></div><div className="filters">{['Todas', ...catalog.units.map(u => u.title)].map(name => <button key={name} className={unit === name ? 'active' : ''} onClick={() => setUnit(name)}>{name}</button>)}</div><div className="sign-grid">{filtered.map(sign => <button key={sign.id} className={selected?.id === sign.id ? 'selected' : ''} onClick={() => openPreview(sign)}><div className="sign-thumb" style={{background:`${sign.color}18`}}>🤟🏻<i style={{background:sign.color}}><Play/></i></div><strong>{sign.term}</strong><span>{sign.unit}</span></button>)}</div>{!filtered.length && <div className="empty"><Search/><h3>No encontramos esa seña</h3><p>Prueba con otra palabra o categoría.</p></div>}</section>{selected && <><button className={`dictionary-backdrop ${previewOpen ? 'open' : ''}`} onClick={() => setPreviewOpen(false)} aria-label="Cerrar video"/><aside className={`sign-preview ${previewOpen ? 'mobile-open' : ''}`}><button className="preview-close" onClick={() => setPreviewOpen(false)} aria-label="Cerrar vista de la seña"><X/></button><div className="preview-video"><SignVideo key={selected.video} src={videoSrc(selected.video)} autoplay={previewOpen && autoplay} loop/></div><span className="eyebrow">{selected.unit}</span><h2>{selected.term}</h2><p>Observa el movimiento completo y repítelo lentamente frente a un espejo.</p><div className="tip"><Sparkles/><span><strong>Consejo</strong>Mira la posición de las manos y también la expresión facial.</span></div></aside></>}</div></div>;
}

function Translator({ catalog, autoplay = true }) {
  const signs = useMemo(() => catalog.units.flatMap(u => u.lessons.flatMap(l => l.signs)), [catalog]); const [text, setText] = useState(''); const [queue, setQueue] = useState([]); const [current, setCurrent] = useState(0); const [listening, setListening] = useState(false); const [translationInfo, setTranslationInfo] = useState({ deletreadas: [], omitidas: [] });
  const translate = input => { const result = crearSecuenciaTraduccion(input, signs); setQueue(result.secuencia); setTranslationInfo(result); setCurrent(0); };
  const listen = () => { const Recognition = window.SpeechRecognition || window.webkitSpeechRecognition; if (!Recognition) return alert('Tu navegador no ofrece reconocimiento de voz. Puedes escribir el texto.'); const rec = new Recognition(); rec.lang='es-GT'; rec.interimResults=false; rec.onstart=()=>setListening(true); rec.onend=()=>setListening(false); rec.onresult=e=>{const value=e.results[0][0].transcript; setText(value); translate(value)}; rec.start(); };
  return <div className="page enter"><div className="page-heading"><span className="eyebrow">HERRAMIENTA DE APOYO</span><h1>De voz y texto a señas</h1><p>Habla o escribe una frase; SingAI usará las señas disponibles y deletreará las demás palabras.</p></div><div className="translator-grid"><section className="translate-input"><div className="translate-head"><Languages/><strong>Español</strong><span>Texto o voz</span></div><textarea value={text} onChange={e=>setText(e.target.value)} placeholder="Escribe una frase o presiona “Hablar”…" maxLength="180"/><div className="translate-actions"><button className={listening ? 'mic listening' : 'mic'} onClick={listen}><Mic/>{listening ? 'Escuchando…' : 'Hablar'}</button><span>{text.length}/180</span><Button onClick={()=>translate(text)} disabled={!text.trim()}>Traducir <ArrowRight/></Button></div></section><section className="translate-output"><div className="translate-head"><span className="sign-icon">🤟🏻</span><strong>Lengua de señas</strong><span>{queue.length ? `${current+1} de ${queue.length}` : 'Resultado'}</span></div>{queue.length ? <><div className="translator-video"><SignVideo key={`${queue[current].video}-${current}`} src={videoSrc(queue[current].video)} autoplay={autoplay} onEnded={()=>current<queue.length-1&&setCurrent(v=>v+1)}/></div>{translationInfo.deletreadas.length > 0 && <p className="spell-note"><strong>Deletreando:</strong> {translationInfo.deletreadas.join(', ')}</p>}<div className="queue">{queue.map((s,i)=><button key={`${s.id}-${i}`} className={`${i===current?'active':''} ${s.tipo==='letra'?'letter':''}`} onClick={()=>setCurrent(i)} title={s.palabraDeletreada ? `Letra de ${s.palabraDeletreada}` : s.term}>{s.etiqueta}</button>)}</div></> : <div className="translate-empty"><div>🤟🏻</div><h3>Tu traducción aparecerá aquí</h3><p>Las palabras sin seña propia se deletrearán automáticamente con el abecedario.</p>{translationInfo.omitidas.length > 0 && <small>No se pudieron representar: {translationInfo.omitidas.join(', ')}</small>}</div>}</section></div><div className="privacy-note"><LockKeyhole/><span><strong>Tu privacidad importa.</strong> El audio se procesa con la función de reconocimiento de tu navegador y no se almacena en SingAI.</span></div></div>;
}

function Ranks({ profile }) {
  const guide = listarRangos(); const current = obtenerRango(profile.xp); const currentIndex = Math.min(Math.floor(current.xpBase / 100), guide.length - 1);
  return <div className="page enter"><div className="page-heading"><span className="eyebrow">TU CAMINO COMPETITIVO</span><h1>Rangos de SingAI</h1><p>Cada 100 XP subes una división. Si pierdes tus cinco vidas, puedes perder XP y bajar de rango.</p></div><section className="rank-overview"><div className="rank-emblem"><Award/></div><div><span>RANGO ACTUAL</span><h2>{current.nombre}</h2><p>{current.esMaximo ? 'Alcanzaste el rango máximo.' : `Te faltan ${current.xpSiguiente - current.xp} XP para ${guide[currentIndex + 1].nombre}.`}</p><div className="rank-progress"><i style={{width:`${current.progreso}%`}}/></div><small>{current.esMaximo ? `${current.xp} XP` : `${current.xp - current.xpBase} / 100 XP`}</small></div></section><div className="rank-section-title"><div><span className="eyebrow">TODAS LAS DIVISIONES</span><h2>Ruta hasta Radiante III</h2></div><span>24 rangos</span></div><section className="rank-roadmap">{guide.map(item => <article key={item.nombre} data-rank={item.rango.toLowerCase()} className={`${item.indice === currentIndex ? 'current' : ''} ${item.indice < currentIndex ? 'reached' : ''}`}><div>{item.indice < currentIndex ? <Check/> : item.indice === currentIndex ? <Crown/> : <Award/>}</div><span>{item.rango}</span><strong>{item.division}</strong><small>{item.xpNecesaria} XP</small>{item.indice === currentIndex && <em>Tu rango</em>}</article>)}</section></div>;
}

function Friends({ social, onRefresh }) {
  const [email, setEmail] = useState(''); const [result, setResult] = useState(null); const [busy, setBusy] = useState(false); const [message, setMessage] = useState(''); const [error, setError] = useState('');
  const ranking = [social.self, ...social.friends].filter(Boolean).sort((a,b) => Number(b.xp || 0) - Number(a.xp || 0));
  const searchFriend = async e => { e.preventDefault(); setBusy(true); setError(''); setMessage(''); try { const found = await api('/social/search',{method:'POST',body:{email}}); setResult(found); if (!found.user) setMessage(found.message); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  const requestFriend = async () => { setBusy(true); setError(''); try { const response = await api('/social/request',{method:'POST',body:{userId:result.user.userId}}); setMessage(response.message); setResult({...result,relation:'pending'}); await onRefresh(); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  const respond = async (requestId, accept) => { setBusy(true); setError(''); try { const response = await api('/social/respond',{method:'POST',body:{requestId,accept}}); setMessage(response.message); await onRefresh(); } catch (err) { setError(err.message); } finally { setBusy(false); } };
  return <div className="page enter"><div className="page-heading row"><div><span className="eyebrow">APRENDAN JUNTOS</span><h1>Amigos y clasificación</h1><p>Agrega personas de SingAI y compitan sanamente por alcanzar el siguiente rango.</p></div><button className="refresh-social" onClick={onRefresh}>Actualizar</button></div><div className="social-grid"><section className="social-card add-friend"><div className="social-card-head"><UserPlus/><div><h2>Agregar amigo</h2><p>Busca su cuenta usando el correo exacto.</p></div></div><form onSubmit={searchFriend}><div className="search-box"><Mail/><input type="email" value={email} onChange={e=>setEmail(e.target.value)} placeholder="amigo@correo.com" required/></div><Button disabled={busy || !email.trim()}>{busy ? 'Buscando…' : 'Buscar'}</Button></form>{result?.user && <div className="friend-result"><div className="friend-avatar">{avatars[result.user.avatar] || '🤟🏻'}</div><div><strong>{result.user.displayName}</strong><span>{obtenerRango(result.user.xp).nombre} · {result.user.xp || 0} XP</span></div>{result.relation === 'accepted' ? <b>Ya son amigos</b> : result.relation === 'pending' ? <b>Solicitud pendiente</b> : <button onClick={requestFriend} disabled={busy}>Agregar</button>}</div>}<Notice text={error}/><Notice text={message} type="success"/></section><section className="social-card inbox"><div className="social-card-head"><Bell/><div><h2>Solicitudes</h2><p>{social.incoming.length ? `${social.incoming.length} por responder` : 'Tu bandeja está al día'}</p></div>{social.incoming.length > 0 && <span>{social.incoming.length}</span>}</div>{social.incoming.length ? <div className="request-list">{social.incoming.map(request => <article key={request.id}><div className="friend-avatar">{avatars[request.fromAvatar] || '🤟🏻'}</div><div><strong>{request.fromName}</strong><small>Quiere competir contigo</small></div><button className="accept" onClick={()=>respond(request.id,true)} disabled={busy}><Check/></button><button className="reject" onClick={()=>respond(request.id,false)} disabled={busy}><X/></button></article>)}</div> : <div className="social-empty"><Bell/><p>Cuando alguien te agregue, su solicitud aparecerá aquí.</p></div>}</section></div><section className="leaderboard"><div className="leaderboard-head"><div><span className="eyebrow">CLASIFICACIÓN PRIVADA</span><h2>Ranking de amigos</h2></div><Medal/></div>{ranking.map((person,index) => { const rank=obtenerRango(person.xp); const isMe=person.userId===social.self?.userId; return <article key={person.userId} className={isMe?'me':''}><div className={`position p${index+1}`}>{index < 3 ? <Medal/> : index+1}</div><div className="friend-avatar">{avatars[person.avatar] || '🤟🏻'}</div><div className="leader-name"><strong>{person.displayName} {isMe && <em>Tú</em>}</strong><span>{rank.nombre}</span></div><div className="leader-xp"><strong>{person.xp || 0}</strong><span>XP</span></div></article>})}{social.friends.length === 0 && <div className="ranking-invite"><Users/><h3>Tu competencia empieza aquí</h3><p>Agrega a tu primer amigo para comparar sus rangos y XP.</p></div>}</section></div>;
}

function Profile({ profile, user, onSaved }) {
  const [form,setForm]=useState(profile); const [message,setMessage]=useState(''); const [busy,setBusy]=useState(false); const rank=obtenerRango(profile.xp); const lastAccess=user.lastSignInAt?new Intl.DateTimeFormat('es-GT',{dateStyle:'medium',timeStyle:'short'}).format(new Date(user.lastSignInAt)):'Primer acceso'; const save=async e=>{e.preventDefault();setBusy(true);try{const r=await api('/profile',{method:'PATCH',body:form});onSaved(r.profile);setMessage('Cambios guardados correctamente.')}finally{setBusy(false)}};
  return <div className="page narrow enter"><div className="page-heading"><span className="eyebrow">TU ESPACIO</span><h1>Mi perfil</h1><p>Personaliza tus metas, nivel y experiencia de aprendizaje.</p></div><section className="profile-card"><div className="profile-cover"><div className="big-avatar">{avatars[form.avatar]}</div><div><h2>{profile.displayName}</h2><p>{user.email}</p></div><span><Award/> {rank.nombre} · {profile.xp} XP</span></div><div className="security-summary"><ShieldCheck/><div><strong>Cuenta protegida</strong><span>Correo verificado · sesión privada</span></div><small>Último acceso: {lastAccess}</small></div><form onSubmit={save}><h3>Información personal</h3><div className="form-grid"><label>Nombre visible<input value={form.displayName} onChange={e=>setForm({...form,displayName:e.target.value})}/></label><label>Objetivo principal<select value={form.learningGoal} onChange={e=>setForm({...form,learningGoal:e.target.value})}><option value="comunicarme">Comunicarme mejor</option><option value="familia">Hablar con mi familia</option><option value="trabajo">Usarlo en mi trabajo</option><option value="curiosidad">Aprender algo nuevo</option></select></label><label>Nivel actual<select value={form.experienceLevel} onChange={e=>setForm({...form,experienceLevel:e.target.value})}><option value="principiante">Principiante</option><option value="intermedio">Intermedio</option><option value="avanzado">Avanzado</option></select></label><label>Categoría favorita<select value={form.preferredCategory} onChange={e=>setForm({...form,preferredCategory:e.target.value})}><option value="abecedario">Abecedario</option><option value="conversaciones">Conversaciones</option><option value="emociones">Emociones</option><option value="dias">Días de la semana</option><option value="acciones">Acciones cotidianas</option></select></label><label>Lecciones diarias<select value={form.dailyGoal} onChange={e=>setForm({...form,dailyGoal:Number(e.target.value)})}>{[1,2,3,4,5].map(n=><option key={n} value={n}>{n} {n===1?'lección':'lecciones'}</option>)}</select></label><label>Días por semana<select value={form.weeklyGoal} onChange={e=>setForm({...form,weeklyGoal:Number(e.target.value)})}>{[2,3,4,5,6,7].map(n=><option key={n} value={n}>{n} días</option>)}</select></label><label className="full-field">Sobre mí<textarea value={form.bio} onChange={e=>setForm({...form,bio:e.target.value})} placeholder="Cuéntanos por qué quieres aprender…" maxLength="180"/></label></div><label className="toggle-row"><input type="checkbox" checked={form.autoplayVideos} onChange={e=>setForm({...form,autoplayVideos:e.target.checked})}/><span><strong>Reproducción automática</strong><small>Iniciar los videos al abrir una seña</small></span></label><h3>Elige tu avatar</h3><div className="avatar-options">{Object.entries(avatars).map(([key,icon])=><button type="button" className={form.avatar===key?'active':''} key={key} title={avatarNames[key]} aria-label={`Usar avatar ${avatarNames[key]}`} onClick={()=>setForm({...form,avatar:key})}>{icon}{form.avatar===key&&<i><Check/></i>}</button>)}</div><Notice text={message} type="success"/><Button disabled={busy}>{busy?'Guardando…':'Guardar cambios'}<Check/></Button></form></section></div>;
}

export default function App() {
  const emptySocial={self:null,incoming:[],sent:[],friends:[]}; const [status,setStatus]=useState('loading'); const [user,setUser]=useState(null); const [profile,setProfile]=useState(null); const [progress,setProgress]=useState({completedLessonIds:[],lessons:[]}); const [social,setSocial]=useState(emptySocial); const [catalog,setCatalog]=useState(null); const [page,setPage]=useState('inicio'); const [lesson,setLesson]=useState(null);
  const refreshSocial=async()=>{const data=await api('/social');setSocial(data);return data};
  const loadPrivate=async()=>{const [me,p,c]=await Promise.all([api('/auth/me'),api('/progress'),api('/catalog')]);setUser(me.user);setProfile(p.profile);setProgress(p);setCatalog(c);try{await refreshSocial()}catch{setSocial(emptySocial)}setStatus('ready')};
  useEffect(()=>{if(session.token)loadPrivate().catch(()=>{session.token=null;setStatus('guest')});else setStatus('guest')},[]);
  useEffect(()=>{if(status!=='ready')return;const timer=setInterval(()=>refreshSocial().catch(()=>{}),30000);return()=>clearInterval(timer)},[status]);
  const onAuth=()=>{setStatus('loading');loadPrivate().catch(()=>setStatus('guest'))}; const logout=()=>{session.token=null;setUser(null);setProfile(null);setSocial(emptySocial);setStatus('guest')};
  useEffect(()=>{if(status!=='ready')return;let lastTouch=0;const touch=()=>{if(Date.now()-lastTouch>60000){session.touch();lastTouch=Date.now()}};const timer=setInterval(()=>{if(!session.token)logout()},60000);['pointerdown','keydown','touchstart'].forEach(name=>window.addEventListener(name,touch,{passive:true}));return()=>{clearInterval(timer);['pointerdown','keydown','touchstart'].forEach(name=>window.removeEventListener(name,touch))}},[status]);
  const syncOwnSocial=updated=>setSocial(current=>({...current,self:current.self?{...current.self,xp:updated.xp,streak:updated.streak,displayName:updated.displayName,avatar:updated.avatar}:current.self}));
  const complete=async(lessonId,score)=>{const r=await api('/progress/complete',{method:'POST',body:{lessonId,score}});setProfile(r.progress);syncOwnSocial(r.progress);const fresh=await api('/progress');setProgress(fresh);return r};
  const mistake=async()=>{const r=await api('/progress/mistake',{method:'POST'});setProfile(r.progress);syncOwnSocial(r.progress);return r};
  if(location.pathname==='/restablecer') return <LinkAction/>;
  if(location.pathname==='/acceso') return <VerifyAction/>;
  if(status==='loading') return <Spinner/>; if(status==='guest') return <AuthScreen onAuth={onAuth}/>; if(!catalog||!profile) return <Spinner/>;
  const saveProfile=updated=>{setProfile(updated);setSocial(current=>({...current,self:current.self?{...current.self,displayName:updated.displayName,avatar:updated.avatar}:current.self}))};
  const pages={inicio:<Welcome profile={profile} catalog={catalog} progress={progress} startLesson={setLesson} setPage={setPage}/>,aprender:<Learn catalog={catalog} progress={progress} startLesson={setLesson}/>,diccionario:<Dictionary catalog={catalog} autoplay={profile.autoplayVideos}/>,traductor:<Translator catalog={catalog} autoplay={profile.autoplayVideos}/>,rangos:<Ranks profile={profile}/>,logros:<Achievements profile={profile} progress={progress}/>,amigos:<Friends social={social} onRefresh={refreshSocial}/>,seguridad:<SecurityCenter user={user}/>,perfil:<Profile profile={profile} user={user} onSaved={saveProfile}/>};
  return <Shell user={user} profile={profile} page={page} setPage={setPage} logout={logout} pendingCount={social.incoming.length}>{pages[page]}{lesson&&<Lesson lesson={lesson} catalog={catalog} profile={profile} autoplay={profile.autoplayVideos} onClose={()=>setLesson(null)} onComplete={complete} onMistake={mistake}/>}</Shell>;
}
